import numpy as np
from scipy.optimize import least_squares
def sim(m,r,sh,rho,h,v0=0,ang=0,c=None,n=1.0,dt=0.002):
    k=c[sh]*rho*r**2/m
    a=np.radians(ang);x=0;y=h;vx=v0*np.cos(a);vy=v0*np.sin(a);t=0
    while y>0:
        v=np.hypot(vx,vy);vx-=k*v**n*vx*dt;vy+=(-9.8-k*v**n*vy)*dt
        x+=vx*dt;y+=vy*dt;t+=dt
    return t,x,np.hypot(vx,vy)
